-- ⚠️ 本机无 MySQL 凭证, 未实跑; 只作语法结构与声明顺序参考
DELIMITER $$
CREATE PROCEDURE p_raise_all(IN p_pct DECIMAL(5,2))
BEGIN
    -- DECLARE 强制顺序: 变量 -> 条件 -> 游标 -> 处理器
    DECLARE v_id   BIGINT;
    DECLARE v_sal  DECIMAL(10,2);
    DECLARE v_done INT DEFAULT 0;
    DECLARE cur_emp CURSOR FOR
        SELECT id, salary FROM employee WHERE status = 1;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN cur_emp;
    read_loop: LOOP
        FETCH cur_emp INTO v_id, v_sal;
        IF v_done = 1 THEN LEAVE read_loop; END IF;   -- CONTINUE 型需自行退出
        UPDATE employee SET salary = v_sal * (1 + p_pct / 100) WHERE id = v_id;
    END LOOP;
    CLOSE cur_emp;
END$$
DELIMITER ;

